<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);$month=$_GET['month']??date('Y-m');$s=stats($pdo,$month);$cats=categoryTotals($pdo,$month);$filename='expense_report_'.$month.'.csv';if(isset($_GET['export'])){header('Content-Type:text/csv');header('Content-Disposition:attachment;filename="'.$filename.'"');$out=fopen('php://output','w');fputcsv($out,['Date','Title','Type','Category','Payment Method','Amount','Notes']);foreach(transactions($pdo,"WHERE substr(t.date,1,7)=?",[$month]) as $r)fputcsv($out,[$r['date'],$r['title'],$r['type'],$r['category'],$r['payment_method'],$r['amount'],$r['notes']]);fclose($out);exit;}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link rel="stylesheet" href="assets/style.css"><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Reports</h1><p>Analyze your spending month by month</p></div><a class="btn primary" href="?month=<?=h($month)?>&export=1">Export CSV</a></header><form class="panel filters"><label>Report Month<input type="month" name="month" value="<?=h($month)?>"></label><button class="btn primary">View Report</button></form><section class="cards"><div class="card"><div class="label">Income</div><div class="value income">₹<?=money($s['income'])?></div></div><div class="card"><div class="label">Expenses</div><div class="value expense">₹<?=money($s['month_expense'])?></div></div><div class="card"><div class="label">Net</div><div class="value">₹<?=money($s['income']-$s['month_expense'])?></div></div></section><div class="grid"><div class="panel"><div class="panel-title"><h2>Category Breakdown</h2></div><div class="chart-box"><?php if($cats):?><canvas id="rchart"></canvas><?php else:?><div class="empty">No data.</div><?php endif;?></div></div><div class="panel"><div class="panel-title"><h2>Category Details</h2></div><?php foreach($cats as $c):?><div class="tx"><div class="avatar"><?=h($c['icon'])?></div><div class="txbody"><b><?=h($c['name'])?></b><span><?=round($c['total']/max(1,$s['month_expense'])*100,1)?>% of monthly expenses</span></div><b>₹<?=money($c['total'])?></b></div><?php endforeach;?></div></div></main></div><script>if(document.getElementById('rchart'))new Chart(document.getElementById('rchart'),{type:'bar',data:{labels:<?=json_encode(array_column($cats,'name'))?>,datasets:[{label:'₹ spent',data:<?=json_encode(array_map('floatval',array_column($cats,'total')))?>}]},options:{responsive:true,maintainAspectRatio:false}});</script></body></html>